let tables = {Tables};
let usage = Usage
| where TimeGenerated < startofday(now()) and IsBillable == true
| where array_length(tables) == 0 or DataType in (tables)
| extend Plan = tostring(column_ifexists("Plan", ""))
| extend Plan = iff(isempty(Plan), "Analytics", Plan);
let days = toscalar(usage | summarize d = dcount(bin(TimeGenerated, 1d)) | project max_of(d, 1));
let total = toscalar(usage | summarize sum(Quantity)) / 1000.0;
usage
| summarize GB = sum(Quantity) / 1000.0 by Table = DataType, Plan
| extend GBPerDay = GB / days
| extend IngestPerMonth = GBPerDay * 30 * case(Plan == "Basic", {PriceBasic}, Plan == "Auxiliary", {PriceAuxiliary}, {PriceAnalytics})
| extend RetentionPerMonth = GBPerDay * max_of(0, {RetentionDays} - iff(Plan == "Analytics", {FreeRetentionDays}, 30)) * {RetentionPrice}
| extend TotalPerMonth = IngestPerMonth + RetentionPerMonth, SharePct = round(100.0 * GB / total, 1)
| summarize GBPerDay = round(sum(GBPerDay), 2), IngestPerMonth = round(sum(IngestPerMonth), 2), RetentionPerMonth = round(sum(RetentionPerMonth), 2), TotalPerMonth = round(sum(TotalPerMonth), 2)
| project GBPerDay

