| where DataType in (top)
| summarize GB = round(sum(Quantity) / 1000.0, 3) by Day = bin(TimeGenerated, 1d), Table = DataType
| order by Day asc

let usage = Usage
| where TimeGenerated < startofday(now()) and IsBillable == true
| extend Plan = tostring(column_ifexists("Plan", ""))
| extend Plan = iff(isempty(Plan), "Analytics", Plan);
let days = toscalar(usage | summarize d = dcount(bin(TimeGenerated, 1d)) | project max_of(d, 1));
let analytics = toscalar(usage | where Plan == "Analytics" | summarize sum(Quantity)) / 1000.0 / days;
let scale = {PriceAnalytics} / 4.30;
// East US Sentinel simplified commitment tiers (USD per day, November 2026), scaled by your Analytics price.
union
    (print Option = "Pay-as-you-go", TierGB = 0, PerDay = analytics * {PriceAnalytics}),
    (datatable(TierGB: long, TierPrice: real) [100, 296.0, 200, 548.0, 300, 800.0, 400, 1037.33, 500, 1265.0, 1000, 2480.0, 2000, 4800.0, 5000, 11550.0]
    | extend Option = strcat(TierGB, " GB/day"), PerDay = scale * (TierPrice + max_of(0.0, analytics - TierGB) * TierPrice / TierGB)
    | project Option, TierGB, PerDay)
| extend AnalyticsGBPerDay = round(analytics, 2), PerMonth = round(PerDay * 30, 2), PerDay = round(PerDay, 2)
| order by TierGB asc
| project Option, AnalyticsGBPerDay, PerDay, PerMonth
